import{z as n,x as o,o as l,c as m,q as r,j as t,D as A,d as a,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"许可证谱系与选择","description":"","frontmatter":{"title":"许可证谱系与选择","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eco-license-spectrum.md","filePath":"llm/eco-license-spectrum.md","lastUpdated":1791063341000}'),p={name:"llm/eco-license-spectrum.md"};function D(d,E,F,c,h,C){const B=o("Mermaid");return l(),m("div",null,[E[2]||(E[2]=r('<h1 id="许可证谱系与选择" tabindex="-1">许可证谱系与选择 <a class="header-anchor" href="#许可证谱系与选择" aria-label="Permalink to &quot;许可证谱系与选择&quot;">​</a></h1><div class="epigraph"><p>「开源」说的不是价格为零，而是使用、研究、修改与再分发的自由；一个模型可以权重随便下，却四项自由一项都不完整。</p><footer>—— 据 Open Source Initiative 的开放源代码定义与自由软件基金会「四项自由」的口径整理</footer></div><p><a href="/llm/pl-map">上一课</a>把推理时的规划与反思收成六族失败：答错先落到族，再用加预算恢复率判归推理侧还是训练侧，诊断先验证器、再搜索、再预算。失败可归因、门禁可画，模型就到了往外发的关口——权重以什么许可发出去，决定生态里谁能接手、接手后能做什么。本课是「开源生态与发布工程」的第一课：先把「开源模型」这个词拆成一条谱系，后课读条款、记衍生账、配卡、钉版本，都默认你已经会用这条谱系说话。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>社区把「开源模型」当成通用标签，实际这是一条四档谱系。第一档是研究专用：早期 Llama 1 的权重只放给申请过的研究者，商用不在授予范围内。第二档是自有社区条款：<a href="/llm/llama-2">Llama 2</a> 起的 Llama 社区许可、Gemma 的使用条款，允许商用，但附加命名、规模门槛与使用政策。第三档是宽松许可：<a href="/llm/mistral-mixtral">Mistral 与 Mixtral</a> 用 Apache 2.0，<a href="/llm/qwen3">Qwen</a> 多数尺寸用 Apache 2.0，<a href="/llm/deepseek-r1">DeepSeek-R1</a> 与 Phi 一族走更简的 MIT——这些是 OSI 意义上接近标准的许可。第四档是全开放：<a href="/llm/olmo-paper">OLMo</a> 把数据、训练代码与权重一起放出，证据层级又高一截。缺口在于：选许可不是选一个名字，而是把「我给下游留下多少自由、保留多少控制」画清楚。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从两个视角画这条谱系。发布者视角问：想保留什么控制？通常是三类——品牌（衍生模型必须怎么命名）、规模（多大的部署要回来谈）、滥用（把可接受使用政策并入条款）。使用者视角问：要什么自由？商用部署、再分发、拿权重继续训练、并进自己的产品，每一项都可能被某一档卡住。谱系的轴因此是五条：权重可得性、商用权、衍生权、附加义务、附加政策。<span class="marginnote">可以把四档谱系想成出租房子：研究专用是「只借给申请过的学生做实验」；社区条款是「可以住，但招牌得写房东名字、住到一定规模回来重谈」；宽松许可是「随便住随便改，留张字条说明房子原本是谁的」；全开放则是连图纸、钥匙、装修清单一起交给你。租客（下游）按自己的用途挑房子，房东（发布方）按想保留的控制权定规矩。</span></p>',7)),(l(),t(s,null,{default:A(()=>[i(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%A0%94%E7%A9%B6%E4%B8%93%E7%94%A8%EF%BC%9A%E6%9D%83%E9%87%8D%E7%94%B3%E8%AF%B7%E5%88%B6%22%5D%20--%3E%20B%5B%22%E8%87%AA%E6%9C%89%E7%A4%BE%E5%8C%BA%E6%9D%A1%E6%AC%BE%EF%BC%9A%E5%95%86%E7%94%A8%E5%8A%A0%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%AE%BD%E6%9D%BE%E8%AE%B8%E5%8F%AF%EF%BC%9AApache%202.0%20%2F%20MIT%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%85%A8%E5%BC%80%E6%94%BE%EF%BC%9A%E6%9D%83%E9%87%8D%E3%80%81%E4%BB%A3%E7%A0%81%E3%80%81%E6%95%B0%E6%8D%AE%E9%BD%90%E6%94%BE%22%5D%0A%20%20AXIS%5B%22%E4%BA%94%E6%9D%A1%E8%BD%B4%EF%BC%9A%E5%8F%AF%E5%BE%97%E6%80%A7%20%2F%20%E5%95%86%E7%94%A8%20%2F%20%E8%A1%8D%E7%94%9F%20%2F%20%E4%B9%89%E5%8A%A1%20%2F%20%E6%94%BF%E7%AD%96%22%5D%20-.-%3E%20A%0A%20%20AXIS%20-.-%3E%20D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("为什么不是人人都选宽松许可？Apache 2.0 附带专利授权段与 NOTICE 要求，MIT 只要求保留版权声明，两者都把商用、修改、再分发的门槛降到最低——但发布者随之失去品牌控制，也失去用条款约束滥用的抓手。Llama 社区许可保留控制的方式是合同式条款：商用开放，但月活越过某个量级要另行申请，衍生模型要带指定命名与出处说明。反过来，为什么不是人人都收着发？生态的参与者按自由度投票：宽松许可的权重被更多框架、更多产品、更多后续研究采纳，形成标准位；收着的许可保住叙事，却把生态位让了出去。"),e("a",{href:"/llm/gemma"},"Gemma"),a(" 与 DeepSeek 在谱系上的位置不同，但都在「控制」与「采用」之间做同一道题，只是答法不同。")],-1)),E[5]||(E[5]=e("p",null,"使用者拿到一份许可，可以用三问把它快速定位到谱系档位：",-1)),(l(),t(s,null,{default:A(()=>[i(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20GET%5B%22%E6%8B%BF%E5%88%B0%E4%B8%80%E4%BB%BD%E6%A8%A1%E5%9E%8B%E8%AE%B8%E5%8F%AF%22%5D%20--%3E%20Q1%7B%22%E8%83%BD%E5%95%86%E7%94%A8%E9%83%A8%E7%BD%B2%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%E4%B8%8D%E8%83%BD%E6%88%96%E9%9C%80%E7%94%B3%E8%AF%B7%7C%20T1%5B%22%E7%A0%94%E7%A9%B6%E4%B8%93%E7%94%A8%E6%A1%A3%22%5D%0A%20%20Q1%20--%3E%7C%E8%83%BD%EF%BC%8C%E4%BD%86%E9%99%84%E5%8A%A0%E6%9D%A1%E4%BB%B6%7C%20T2%5B%22%E7%A4%BE%E5%8C%BA%E6%9D%A1%E6%AC%BE%E6%A1%A3%EF%BC%9A%E8%AF%BB%E4%BE%8B%E5%A4%96%E4%B8%8E%E6%94%BF%E7%AD%96%22%5D%0A%20%20Q1%20--%3E%7C%E8%83%BD%EF%BC%8C%E6%97%A0%E9%A2%9D%E5%A4%96%E6%9D%A1%E4%BB%B6%7C%20Q2%7B%22%E6%95%B0%E6%8D%AE%E4%B8%8E%E4%BB%A3%E7%A0%81%E4%B9%9F%E5%BC%80%E6%94%BE%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%E5%8F%AA%E6%9C%89%E6%9D%83%E9%87%8D%E4%B8%8E%E6%96%87%E6%A1%A3%7C%20T3%5B%22%E5%AE%BD%E6%9D%BE%E8%AE%B8%E5%8F%AF%E6%A1%A3%22%5D%0A%20%20Q2%20--%3E%7C%E5%85%A8%E6%94%BE%7C%20T4%5B%22%E5%85%A8%E5%BC%80%E6%94%BE%E6%A1%A3%22%5D%0A%20%20T1%20--%3E%20FIN%5B%22%E5%86%8D%E8%BF%87%E4%BA%94%E6%9D%A1%E8%BD%B4%EF%BC%9A%E5%95%86%E7%94%A8%20%2F%20%E8%A1%8D%E7%94%9F%20%2F%20%E4%B9%89%E5%8A%A1%20%2F%20%E6%94%BF%E7%AD%96%20%2F%20%E5%8F%AF%E5%BE%97%E6%80%A7%22%5D%0A%20%20T2%20--%3E%20FIN%0A%20%20T3%20--%3E%20FIN%0A%20%20T4%20--%3E%20FIN%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">「宽松许可」指对商用、修改、再分发几乎不加限制的许可。Apache 2.0 比 MIT 多一段专利授权（使用权重不构成专利侵权索赔的相互承诺）和一份 NOTICE 保留要求；MIT 简到只剩「保留版权声明」。对模型权重而言两者的实际约束差别很小，选型时更该看的是发布方的使用政策和历史口碑，而不是许可名字本身。</span></p><p><span class="marginnote">Llama 社区许可里传播最广的一条：月活跃用户超过 7 亿需向 Meta 申请特别许可。这一条让「开源」的 Llama 在超大厂那里并不自动可用——读许可先读例外条款。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>谱系会漂移。Llama 1 是研究许可，Llama 2 起换成社区许可；个别厂商把初版的研究许可在后续版本放宽，也有反向收紧的例子。所以引用任何模型的许可都要带版本号，「它一直是 X 许可」是本课要消灭的说法。本课也不给法律意见：谱系是工程定位工具，签合之前读官方文本。<span class="marginnote">初学者容易把「能免费下载」当成「开源」。判断标准不是价格而是四项自由：能用、能研究、能改、能再分发。Llama 的权重人人可下，但商用有规模门槛、衍生有命名要求，按 OSI 口径它不算开源——这也是社区围绕「开源大模型」这个词争论多年的根源：各方说的根本不是同一件事。</span>最后，许可只约束权重文件与文档这些「作品」，不自动约束模型生成出来的行为——行为边界靠评测与使用政策，那是<a href="/llm/aeval-map">对齐评测</a>已经处理过的另一条线。后课默认你已经能按这五条轴给任何新发布定位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>「开源模型」是四档谱系：研究专用、自有社区条款、宽松许可（Apache 2.0 / MIT）、全开放（连数据与代码）。</li><li>定位一条许可用五条轴：权重可得性、商用权、衍生权、附加义务、附加政策。</li><li>发布者在「控制」（品牌、规模门槛、滥用约束）与「采用」（生态位）之间取舍；使用者按同样五条轴检查自己要的自由。</li><li>许可随版本漂移，引用必须带版本；谱系是工程定位，不是法律意见。</li><li>出处：Open Source Initiative 开源定义；Llama 社区许可、Gemma 使用条款、Apache 2.0、MIT 许可文本；OLMo、DeepSeek-R1、Qwen、Mistral 官方发布口径，按本课程整理。</li></ul>',6))])}const u=n(p,[["render",D]]);export{f as __pageData,u as default};
